from decimal import Decimal, InvalidOperation


def _value(source: dict | None, key: str) -> object:
    if source is None:
        return ""
    return source.get(key, "")


def _numeric(value: object) -> Decimal:
    if value == "" or value is None:
        return Decimal("0")
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal("0")


def _lookup(
    tables: dict | None,
    table_name: str,
    key_col: str,
    key_val: object,
    out_col: str,
) -> object:
    if not tables:
        return ""

    rows = tables.get(table_name, [])
    for row in rows:
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get(key_col, "") == key_val:
            return row.get(out_col, "")
    return ""


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    errors: list[dict] = []

    if table == "ORD_HEADER":
        disc_pct = _numeric(_value(record, "DISC_PCT"))

        if event in ("INSERT", "UPDATE"):
            if not (disc_pct >= Decimal("0") and disc_pct <= Decimal("100")):
                errors.append(
                    {
                        "code": "E5001",
                        "message": "Discount out of range",
                        "severity": "BLOCK",
                    }
                )

        if event == "UPDATE":
            owner_uid = _value(record, "OWNER_UID")
            role = _lookup(
                tables, "USR_MASTER", "USR_ID", owner_uid, "ROLE_ID"
            )
            if disc_pct > Decimal("20") and role != "MGR" and role != "ADMIN":
                errors.append(
                    {
                        "code": "E5002",
                        "message": "Discount over 20 percent requires manager role",
                        "severity": "BLOCK",
                    }
                )

            old_status = _value(old, "STAT_CD")
            status = _value(record, "STAT_CD")
            if old_status == "I" and status != "I" and status != "X":
                errors.append(
                    {
                        "code": "E5003",
                        "message": "Invoiced order can only be cancelled",
                        "severity": "BLOCK",
                    }
                )

    elif table == "ORD_LINE":
        qty = _numeric(_value(record, "QTY"))

        if event in ("INSERT", "UPDATE"):
            if not qty > Decimal("0"):
                errors.append(
                    {
                        "code": "E5004",
                        "message": "Quantity must be positive",
                        "severity": "BLOCK",
                    }
                )

        if event == "INSERT":
            product_id = _value(record, "PROD_ID")
            active = _lookup(
                tables, "PROD_MASTER", "PROD_ID", product_id, "ACTIVE_FLG"
            )
            if active != "Y":
                errors.append(
                    {
                        "code": "E5005",
                        "message": "Product not active",
                        "severity": "BLOCK",
                    }
                )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
